import {
  isAsciiLetterOrDigit,
  isSpace,
  toLowerAscii,
} from "./chars.mjs";
import { extractPlainText } from "./inline.mjs";

export function createTocState() {
  return {
    counts: Object.create(null),
    emptyCount: 0,
  };
}

function slugify(value) {
  const plain = extractPlainText(value);
  const lower = toLowerAscii(plain);
  let result = "";
  let lastWasDash = false;

  for (let index = 0; index < lower.length; index += 1) {
    const character = lower[index];

    if (isAsciiLetterOrDigit(character) || character === "_") {
      result += character;
      lastWasDash = false;
      continue;
    }

    if ((isSpace(character) || character === "-") && result.length > 0 && !lastWasDash) {
      result += "-";
      lastWasDash = true;
    }
  }

  while (result.endsWith("-")) {
    result = result.slice(0, -1);
  }

  return result;
}

export function createHeadingId(value, state) {
  const base = slugify(value);

  if (base.length === 0) {
    state.emptyCount += 1;
    return `_${state.emptyCount}`;
  }

  const seen = state.counts[base] || 0;
  state.counts[base] = seen + 1;

  if (seen === 0) {
    return base;
  }

  return `${base}_${seen}`;
}

