export function splitLines(value) {
  const lines = [];
  let start = 0;

  for (let index = 0; index < value.length; index += 1) {
    if (value[index] === "\n") {
      let line = value.slice(start, index);

      if (line.endsWith("\r")) {
        line = line.slice(0, -1);
      }

      lines.push(line);
      start = index + 1;
    }
  }

  let tail = value.slice(start);

  if (tail.endsWith("\r")) {
    tail = tail.slice(0, -1);
  }

  lines.push(tail);
  return lines;
}

export function isSpace(character) {
  return character === " " || character === "\t";
}

export function isLineBreak(character) {
  return character === "\n" || character === "\r";
}

export function isWhitespace(character) {
  return isSpace(character) || isLineBreak(character);
}

export function isBlankLine(line) {
  for (let index = 0; index < line.length; index += 1) {
    if (!isSpace(line[index])) {
      return false;
    }
  }

  return true;
}

export function trimSpaces(value) {
  let start = 0;
  let end = value.length;

  while (start < end && isSpace(value[start])) {
    start += 1;
  }

  while (end > start && isSpace(value[end - 1])) {
    end -= 1;
  }

  return value.slice(start, end);
}

export function trimAllWhitespace(value) {
  let start = 0;
  let end = value.length;

  while (start < end && isWhitespace(value[start])) {
    start += 1;
  }

  while (end > start && isWhitespace(value[end - 1])) {
    end -= 1;
  }

  return value.slice(start, end);
}

export function startsWith(value, prefix, offset = 0) {
  if (offset + prefix.length > value.length) {
    return false;
  }

  for (let index = 0; index < prefix.length; index += 1) {
    if (value[offset + index] !== prefix[index]) {
      return false;
    }
  }

  return true;
}

export function countRun(value, offset, character) {
  let count = 0;

  while (offset + count < value.length && value[offset + count] === character) {
    count += 1;
  }

  return count;
}

export function isAsciiLetter(character) {
  return (
    (character >= "a" && character <= "z") ||
    (character >= "A" && character <= "Z")
  );
}

export function isDigit(character) {
  return character >= "0" && character <= "9";
}

export function isAsciiLetterOrDigit(character) {
  return isAsciiLetter(character) || isDigit(character);
}

export function isIdentifierStart(character) {
  return isAsciiLetter(character) || character === "_" || character === "$";
}

export function isIdentifierPart(character) {
  return isIdentifierStart(character) || isDigit(character) || character === "-";
}

export function toLowerAscii(value) {
  let result = "";

  for (let index = 0; index < value.length; index += 1) {
    const character = value[index];

    if (character >= "A" && character <= "Z") {
      result += String.fromCharCode(character.charCodeAt(0) + 32);
    } else {
      result += character;
    }
  }

  return result;
}

export function basename(path) {
  if (path.length === 0) {
    return path;
  }

  let end = path.length;

  while (end > 0 && path[end - 1] === "/") {
    end -= 1;
  }

  let start = end - 1;

  while (start >= 0 && path[start] !== "/") {
    start -= 1;
  }

  return path.slice(start + 1, end);
}

export function repeat(value, count) {
  let result = "";

  for (let index = 0; index < count; index += 1) {
    result += value;
  }

  return result;
}

